VenditeMensili() = { 120, 135, 142, 138, 155, 160, 148, 165, 172, 158 }
SMA3 = TIMESERIES.TSMA(VenditeMensili(), 3)
SMA6 = TIMESERIES.TSMA(VenditeMensili(), 6)
PRINT "Mese  Vendite  SMA(3)  SMA(6)"
PRINT "----  -------  ------  ------"
FOR I = 0 TO UBOUND(VenditeMensili())
  PRINT PADL(CSTR(I+1),4," "); "  ";
  PRINT PADL(CSTR(VenditeMensili(I)),7," "); "  ";
  IF I >= 2 THEN PRINT FORMAT(SMA3(I),"#.0"); ELSE PRINT "   -";
  PRINT "     ";
  IF I >= 5 THEN PRINT FORMAT(SMA6(I),"#.0") ELSE PRINT "-"
NEXT I

DIM Prezzi() = { 10,10,10,10,10,10, 20,20,20,20,20,20, 15,15,15,15,15,15 }
SMA = TIMESERIES.TSMA(Prezzi(), 5)
EMA = TIMESERIES.TSEMA(Prezzi(), 5)
PRINT "Confronto reattivita' al cambio regime:"
PRINT "Giorno  Prezzo  SMA(5)  EMA(5)"
FOR I = 5 TO 12
  PRINT PADL(CSTR(I+1),6," "); "  ";
  PRINT FORMAT(Prezzi(I),"#.0"); "   ";
  PRINT FORMAT(SMA(I),"#.00"); "   ";
  PRINT FORMAT(EMA(I),"#.00")
NEXT I
PRINT "EMA reagisce prima della SMA al cambio."
